#include <SDL.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#define W 1280
#define H 720
static SDL_Window *win; static SDL_Renderer *ren; static SDL_GameController *pad;
static int screen=0,select_game=0,turn=0,mode=0,orient=0,wx=0,wy=0,walls[2]={10,10};
static int hx[2]={4,4},hy[2]={0,8}; static unsigned char edge[9][9][4];
static float pos[2]={0,0},speed[2]={0,0},dist[2]={0,0};
static void color(int r,int g,int b){SDL_SetRenderDrawColor(ren,r,g,b,255);} static void rect(int x,int y,int w,int h){SDL_Rect a={x,y,w,h};SDL_RenderFillRect(ren,&a);} static void line(int x,int y,int xx,int yy){SDL_RenderDrawLine(ren,x,y,xx,yy);}
static void glyph(int x,int y,const char*s,int scale){ /* small built-in block font */
 static const char *alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789:- /";
 static const unsigned short bits[]={0x7bed,0x7aeb,0x724e,0x7b6b,0x79cf,0x79c4,0x72ee,0x5bed,0x7497,0x124e,0x5acd,0x4927,0x5f7b,0x5b6b,0x7b6f,0x7bc4,0x7b7f,0x7be5,0x72e7,0x7492,0x5b6f,0x5b6a,0x5f7f,0x5aad,0x5a92,0x74cf,0x7b6f,0x2492,0x73cf,0x73ef,0x5bef,0x7b7f,0x7b7d,0x1248,0x7b7f,0x7bef,0x0208,0x0000,0x0000,0x0000,0x0000};
 for(;*s;s++,x+=4*scale){const char *p=strchr(alphabet,*s);if(!p)continue;unsigned short b=bits[p-alphabet];for(int j=0;j<5;j++)for(int i=0;i<3;i++)if(b&(1<<(14-j*3-i)))rect(x+i*scale,y+j*scale,scale,scale);}}
static int reachable(int who){int seen[9][9]={0},qx[81],qy[81],a=0,b=0;qx[b]=hx[who];qy[b++]=hy[who];seen[hy[who]][hx[who]]=1;int dx[]={0,1,0,-1},dy[]={-1,0,1,0};while(a<b){int x=qx[a],y=qy[a++];if(y==(who?0:8))return 1;for(int d=0;d<4;d++){int xx=x+dx[d],yy=y+dy[d];if(xx>=0&&xx<9&&yy>=0&&yy<9&&!seen[yy][xx]&&!edge[y][x][d]){seen[yy][xx]=1;qx[b]=xx;qy[b++]=yy;}}}return 0;}
static void wall(int x,int y,int o,int set){if(o==0){edge[y][x][2]=set;edge[y+1][x][0]=set;edge[y][x+1][2]=set;edge[y+1][x+1][0]=set;}else{edge[y][x][1]=set;edge[y][x+1][3]=set;edge[y+1][x][1]=set;edge[y+1][x+1][3]=set;}}
static int canwall(int x,int y,int o){if(x<0||y<0||x>7||y>7)return 0;if(o==0){if(edge[y][x][2]||edge[y][x+1][2]||edge[y][x][1]&&edge[y+1][x][1])return 0;}else if(edge[y][x][1]||edge[y+1][x][1]||edge[y][x][2]&&edge[y][x+1][2])return 0;wall(x,y,o,1);int ok=reachable(0)&&reachable(1);wall(x,y,o,0);return ok;}
static void resetq(void){memset(edge,0,sizeof edge);hx[0]=hx[1]=4;hy[0]=0;hy[1]=8;walls[0]=walls[1]=10;turn=mode=orient=wx=wy=0;}
static void moveq(int dx,int dy){if(mode){wx=SDL_max(0,SDL_min(7,wx+dx));wy=SDL_max(0,SDL_min(7,wy+dy));return;}int d=dx==1?1:dx==-1?3:dy==1?2:0;int x=hx[turn],y=hy[turn],xx=x+dx,yy=y+dy;if(xx<0||xx>8||yy<0||yy>8||edge[y][x][d])return;if(xx==hx[1-turn]&&yy==hy[1-turn]){int nx=xx+dx,ny=yy+dy;if(nx>=0&&nx<9&&ny>=0&&ny<9&&!edge[yy][xx][d]){xx=nx;yy=ny;}else return;}hx[turn]=xx;hy[turn]=yy;if(yy==(turn?0:8))screen=3;else turn=1-turn;}
static void drawq(void){color(14,19,32);SDL_RenderClear(ren);color(230,235,245);glyph(35,24,"QUORIDOR",5);glyph(850,35,turn?"PLAYER 2":"PLAYER 1",4);char t[80];sprintf(t,"P1 WALLS %d  P2 WALLS %d",walls[0],walls[1]);glyph(850,105,t,3);glyph(850,180,mode?"WALL MODE":"MOVE MODE",3);glyph(850,230,orient?"VERTICAL":"HORIZONTAL",3);glyph(850,310,"L1 MODE R1 ROTATE",2);glyph(850,350,"A PLACE OR SELECT",2);glyph(850,390,"MENU BACK",2);int ox=95,oy=125,s=58;for(int y=0;y<9;y++)for(int x=0;x<9;x++){color((x+y)%2?44:54,72,91);rect(ox+x*s,oy+y*s,s-5,s-5);if(edge[y][x][1]){color(255,183,62);rect(ox+x*s+s-6,oy+y*s,7,s-3);}if(edge[y][x][2]){color(255,183,62);rect(ox+x*s,oy+y*s+s-6,s-3,7);}}for(int p=0;p<2;p++){color(p?255:55,p?92:206,p?90:255);rect(ox+hx[p]*s+12,oy+hy[p]*s+12,29,29);}if(mode){color(250,250,120);if(!orient)rect(ox+wx*s,oy+wy*s+s-6,s*2-5,6);else rect(ox+wx*s+s-6,oy+wy*s,6,s*2-5);}}
static void raceview(int p,int top){int y0=top?0:360; color(8,14,28);rect(0,y0,W,360);color(24,45,80);rect(0,y0+38,W,126);color(38,90,93);rect(0,y0+164,W,196);float bend=sinf(dist[p]*.002f)*.8f;for(int z=1;z<=40;z++){float depth=(float)z/40;int y=y0+164+(int)(196*(1-depth)*(1-depth));float perspective=1-depth;int center=W/2+(int)((bend*sinf(dist[p]*.001f+depth*3)*140-pos[p]*160)*perspective);int half=(int)(450*perspective+15);color((z/3)%2?52:58,(z/3)%2?54:58,(z/3)%2?65:70);rect(center-half,y,half*2,SDL_max(2,(int)(12*perspective)));color(240,220,110);rect(center-half,y,SDL_max(2,(int)(10*perspective)),3);rect(center+half-5,y,SDL_max(2,(int)(10*perspective)),3);if(z%5==0){color(235,235,235);rect(center-3,y,6,SDL_max(2,(int)(10*perspective)));}}color(p?255:65,p?90:190,p?80:255);rect(W/2-35,y0+267,70,28);rect(W/2-24,y0+254,48,18);color(245,245,245);char s[80];sprintf(s,"P%d SPEED %03d  LAP %d",p+1,(int)(speed[p]*300),1+(int)(dist[p]/10000));glyph(25,y0+18,s,3);}
static void inputrace(int p,int dir,int accel,int brake,float dt){speed[p]+=((accel?.60f:-.24f)-(brake?.9f:0))*dt;speed[p]=SDL_max(0,SDL_min(1,speed[p]));pos[p]+=dir*dt*(.35f+speed[p]*1.25f);pos[p]=SDL_max(-2,SDL_min(2,pos[p]));if(fabsf(pos[p])>1.15f)speed[p]*=1-.7f*dt;dist[p]+=speed[p]*dt*650;}
static int key[SDL_NUM_SCANCODES];static void drawmenu(void){color(12,18,32);SDL_RenderClear(ren);color(235,240,255);glyph(200,90,"ZUZU2P V1:0",9);glyph(260,280,select_game?"  QUORIDOR":"- QUORIDOR",6);glyph(260,380,select_game?"- SPLIT RACER":"  SPLIT RACER",6);glyph(280,550,"A SELECT  MENU EXIT",3);}
int main(void){if(SDL_Init(SDL_INIT_VIDEO|SDL_INIT_GAMECONTROLLER)<0)return 1;win=SDL_CreateWindow("ZUZU2P v1.0",SDL_WINDOWPOS_CENTERED,SDL_WINDOWPOS_CENTERED,W,H,SDL_WINDOW_FULLSCREEN_DESKTOP);ren=SDL_CreateRenderer(win,-1,SDL_RENDERER_ACCELERATED);if(!ren)return 2;SDL_RenderSetLogicalSize(ren,W,H);for(int i=0;i<SDL_NumJoysticks();i++)if(SDL_IsGameController(i)){pad=SDL_GameControllerOpen(i);break;}int run=1;Uint32 last=SDL_GetTicks();while(run){SDL_Event e;while(SDL_PollEvent(&e)){if(e.type==SDL_QUIT)run=0;if(e.type==SDL_KEYDOWN){key[e.key.keysym.scancode]=1;int k=e.key.keysym.sym;if(k==SDLK_ESCAPE){if(screen)screen=0;else run=0;}else if(screen==0){if(k==SDLK_UP||k==SDLK_DOWN)select_game^=1;if(k==SDLK_RETURN||k==SDLK_SPACE){screen=select_game?2:1;if(screen==1)resetq();else memset(pos,0,sizeof pos),memset(speed,0,sizeof speed),memset(dist,0,sizeof dist);}}else if(screen==1){if(k==SDLK_TAB)mode^=1;else if(k==SDLK_r)orient^=1;else if(k==SDLK_RETURN||k==SDLK_SPACE){if(mode&&walls[turn]&&canwall(wx,wy,orient)){wall(wx,wy,orient,1);walls[turn]--;turn^=1;}}else if(k==SDLK_UP)moveq(0,-1);else if(k==SDLK_DOWN)moveq(0,1);else if(k==SDLK_LEFT)moveq(-1,0);else if(k==SDLK_RIGHT)moveq(1,0);}else if(screen==3&&k==SDLK_RETURN){resetq();screen=1;}}if(e.type==SDL_KEYUP)key[e.key.keysym.scancode]=0;if(e.type==SDL_CONTROLLERBUTTONDOWN){int b=e.cbutton.button;if(b==SDL_CONTROLLER_BUTTON_START||b==SDL_CONTROLLER_BUTTON_BACK){screen=0;continue;}if(screen==0){if(b==SDL_CONTROLLER_BUTTON_DPAD_UP||b==SDL_CONTROLLER_BUTTON_DPAD_DOWN)select_game^=1;if(b==SDL_CONTROLLER_BUTTON_A){screen=select_game?2:1;resetq();}}else if(screen==1){if(b==SDL_CONTROLLER_BUTTON_LEFTSHOULDER)mode^=1;else if(b==SDL_CONTROLLER_BUTTON_RIGHTSHOULDER)orient^=1;else if(b==SDL_CONTROLLER_BUTTON_A&&mode&&walls[turn]&&canwall(wx,wy,orient)){wall(wx,wy,orient,1);walls[turn]--;turn^=1;}else if(b==SDL_CONTROLLER_BUTTON_DPAD_UP||b==SDL_CONTROLLER_BUTTON_Y)moveq(0,-1);else if(b==SDL_CONTROLLER_BUTTON_DPAD_DOWN||b==SDL_CONTROLLER_BUTTON_A)moveq(0,1);else if(b==SDL_CONTROLLER_BUTTON_DPAD_LEFT||b==SDL_CONTROLLER_BUTTON_X)moveq(-1,0);else if(b==SDL_CONTROLLER_BUTTON_DPAD_RIGHT||b==SDL_CONTROLLER_BUTTON_B)moveq(1,0);}}}Uint32 now=SDL_GetTicks();float dt=SDL_min(.05f,(now-last)/1000.f);last=now;if(screen==0)drawmenu();else if(screen==1||screen==3){drawq();if(screen==3){color(255,250,180);glyph(850,460,turn?"P2 WINS":"P1 WINS",4);}}else{int a=0,b=0,ac=0,br=0,c=0,d=0,ac2=0,br2=0;if(pad){a=SDL_GameControllerGetButton(pad,SDL_CONTROLLER_BUTTON_DPAD_RIGHT)-SDL_GameControllerGetButton(pad,SDL_CONTROLLER_BUTTON_DPAD_LEFT);b=SDL_GameControllerGetButton(pad,SDL_CONTROLLER_BUTTON_B)-SDL_GameControllerGetButton(pad,SDL_CONTROLLER_BUTTON_X);ac=SDL_GameControllerGetButton(pad,SDL_CONTROLLER_BUTTON_DPAD_UP);br=SDL_GameControllerGetButton(pad,SDL_CONTROLLER_BUTTON_DPAD_DOWN);ac2=SDL_GameControllerGetButton(pad,SDL_CONTROLLER_BUTTON_Y);br2=SDL_GameControllerGetButton(pad,SDL_CONTROLLER_BUTTON_A);int lx=SDL_GameControllerGetAxis(pad,SDL_CONTROLLER_AXIS_LEFTX),rx=SDL_GameControllerGetAxis(pad,SDL_CONTROLLER_AXIS_RIGHTX);if(abs(lx)>9000)a=lx>0?1:-1;if(abs(rx)>9000)b=rx>0?1:-1;}c=key[SDL_SCANCODE_RIGHT]-key[SDL_SCANCODE_LEFT];d=key[SDL_SCANCODE_D]-key[SDL_SCANCODE_A];inputrace(0,a?a:c,ac||key[SDL_SCANCODE_UP],br||key[SDL_SCANCODE_DOWN],dt);inputrace(1,b?b:d,ac2||key[SDL_SCANCODE_W],br2||key[SDL_SCANCODE_S],dt);raceview(0,1);raceview(1,0);color(245,245,245);rect(0,358,W,4);}SDL_RenderPresent(ren);SDL_Delay(16);}if(pad)SDL_GameControllerClose(pad);SDL_DestroyRenderer(ren);SDL_DestroyWindow(win);SDL_Quit();return 0;}
